# Temporada 0 · português do Brasil. Mesmo formato do inglês.
PT = {
 '2026-11-27': ('A cafeína melhora seu desempenho', 'A Sociedade Internacional de Nutrição Esportiva conclui que de 3 a 6 mg de cafeína por quilo de peso, cerca de 60 minutos antes, melhoram o desempenho em força e resistência. Se você treina tarde, ela pode tirar seu sono; se tem pressão alta ou é sensível, consulte antes.', '', 'Se você toma café antes de treinar, assim aproveita sem perder o sono.'),
 '2026-11-28': ('Comer devagar sacia mais', 'Num estudo com mulheres, comer o mesmo prato devagar, com mordidas pequenas e mastigando bem, fez com que comessem cerca de 70 kcal a menos do que comendo rápido, e elas se sentiram igualmente satisfeitas ou mais.', '', 'Um truque grátis para comer menos sem passar fome.'),
 '2026-11-29': ('A proteína vegetal também constrói músculo', 'A proteína vegetal costuma ter menos leucina, o aminoácido que mais ativa a construção de músculo. Uma revisão conclui que isso se compensa combinando fontes (leguminosas, cereais, soja) e comendo um pouco mais.', '', 'Se você come pouca carne, também pode ganhar músculo.'),
 '2026-11-30': ('Pouca gordura ou poucos carboidratos: tanto faz', 'No estudo DIETFITS, 609 adultos seguiram por um ano uma dieta pobre em gordura ou uma pobre em carboidratos, ambas de boa qualidade. Perderam peso parecido, e nem a genética nem a insulina previram quem se dava melhor com cada uma.', '', 'A melhor dieta é a que você consegue manter.'),
 '2026-12-01': (None, 'YouTube · Spotify · Apple Music', '', 'Um riff de ritmo constante para aquecer com energia.'),
 '2026-12-02': ('A dor muscular não é ácido lático', 'A dor muscular tardia não é causada pelo ácido lático. Já em 1983, um estudo comparou corridas em descida e no plano: a descida causou muito mais dor muscular com menos lactato no sangue. A dor que aparece 24 a 72 horas depois vem de microlesões nas fibras e da inflamação que inicia o reparo, sobretudo após a fase de descer o peso.', '', 'Se amanhã doer, você saberá que não é «ácido» e que pode se mexer de leve.'),
 '2026-12-03': ('Pular refeições não freia seu metabolismo', 'Num estudo com pessoas saudáveis que jejuaram 84 horas, o gasto energético em repouso não caiu: subiu cerca de 14 % no terceiro dia, pelo aumento da noradrenalina. O «modo de inanição» que freia o metabolismo aparece com semanas comendo pouco, não com um jejum curto.', '', 'Para jejuar sem medo de «quebrar» seu metabolismo.'),
 '2026-12-04': (None, 'YouTube · Spotify · Apple Music', '', 'Para o dia em que você volta depois de uns dias sem treinar: voltar é o que conta.'),
 '2026-12-05': (None, 'Livrarias · eBook · Audiolivro', 'Crimes reais, conteúdo pesado. Em espanhol', 'Para seu dia de descanso: uma leitura envolvente que ajuda a desligar.', ('Hábitos Atômicos – James Clear (2018)', 'Livrarias · eBook · Audiolivro', '', 'Pequenas mudanças que se somam a cada dia: a mesma ideia da sua sequência.')),
 '2026-12-06': ('A proteína queima calorias ao ser digerida', 'Digerir a proteína gasta de 20 a 30 % das suas calorias, contra 5 a 10 % dos carboidratos e 0 a 3 % das gorduras. Além disso, é o nutriente que mais sacia, por isso as refeições ricas em proteína deixam você satisfeito por mais tempo.', '', 'Ajuda você a escolher refeições que saciam e cuidam do seu músculo.'),
 '2026-12-07': ('Quanta água você precisa por dia', 'A Autoridade Europeia para a Segurança dos Alimentos fixa uma ingestão adequada de água total de 2,0 litros por dia para mulheres e 2,5 litros para homens, contando a que vem dos alimentos (cerca de 20 %). Em bebidas, seriam cerca de 1,6 e 2,0 litros. Com calor ou exercício, precisa-se de mais. Um guia prático: urina amarelo-clara indica boa hidratação; urina escura, que falta água.', '', 'Para saber quanto beber de acordo com seu corpo, sem números decorados.'),
 '2026-12-08': ('A gordura sai pelos pulmões', 'Quando você perde 10 kg de gordura, cerca de 8,4 kg saem como dióxido de carbono pela respiração e o resto como água. Respirar mais rápido não emagrece: o que manda é gastar mais energia do que você come.', '', 'Entender para onde vai a gordura tira muitos mitos do caminho.'),
 '2026-12-09': ('The Wild Project – episódios com Javier Santaolalla', 'YouTube · Spotify · Apple Podcasts', 'Os episódios #311 e #348 estão só no YouTube. Em espanhol', 'Ciência contada com paixão: entender como o mundo funciona também treina a mente. Ótimo para ouvir caminhando.'),
 '2026-12-10': ('A janela anabólica é ampla', 'Uma meta-análise descobriu que o suposto benefício de tomar proteína logo após o treino desaparecia ao igualar a proteína total do dia. O que mais importa é quanta proteína você come no dia, dividida em várias refeições.', '', 'Para você não correr para comer depois de treinar se não tiver vontade.'),
 '2026-12-11': (None, 'PC · Xbox Series X|S · PS5', 'Ação no ritmo da música', 'Tudo se move no ritmo da música, como um bom treino. Um prêmio para seu dia de folga.'),
 '2026-12-12': ('A primeira força vem do cérebro', 'Nas primeiras semanas de treino, quase toda a força que você ganha vem do sistema nervoso, não de músculo novo. Um estudo clássico mediu a atividade elétrica dos músculos e viu que no começo melhora sobretudo o recrutamento das fibras, e que a hipertrofia ganha protagonismo depois. Por isso um iniciante aumenta o peso muito rápido sem parecer maior.', '', 'Explica por que no começo você aumenta o peso rápido, embora o músculo demore.'),
 '2026-12-13': (None, 'Aluguel ou compra conforme seu país (consulte o JustWatch)', 'Ganhou 3 Oscars', 'Sobre a disciplina extrema e seu preço: se esforçar sim, se quebrar não.'),
 '2026-12-14': ('A fome tem horário', 'A grelina, o hormônio da fome, sobe logo antes dos seus horários habituais de refeição e cai depois de comer. Por isso, ao começar um jejum, a fome aparece em horários fixos. Com constância, o corpo se acostuma ao novo horário.', '', 'Ajuda você a escolher o horário da sua janela para passar menos fome.'),
 '2026-12-15': ('As calorias líquidas não saciam', 'Num estudo, acrescentar 450 kcal por dia em refrigerante fez as pessoas engordarem, porque não comiam menos depois. Quando essas mesmas calorias vinham de balas de goma, elas compensavam comendo menos no resto do dia.', '', 'Uma mudança fácil: o que você bebe também conta.'),
 '2026-12-16': (None, 'Livrarias · eBook', 'Tem série na Netflix. Em espanhol', 'Uma história sobre perseguir o que você quer de verdade, para desligar no seu dia de descanso.'),
 '2026-12-17': ('Mexer-se sem perceber', '16 pessoas comeram 1.000 kcal a mais por dia durante 8 semanas. Algumas ganharam até 10 vezes mais gordura que outras, e a diferença foi explicada pelo gasto de se mexer fora do exercício: ficar em pé, caminhar, gesticular.', '', 'Os passos e o se mexer durante o dia somam mais do que você imagina.'),
 '2026-12-18': ('Neverender – Justice e Tame Impala', 'YouTube · Spotify · Apple Music', '', 'Eletrônica de pulso constante, perfeita para cardio leve ou alongamentos.'),
 '2026-12-19': ('Pesos leves também constroem músculo', 'Uma meta-análise descobriu que treinar com cargas leves (até 30 % do seu máximo) chegando perto da falha produz um crescimento muscular parecido ao das cargas pesadas. A força máxima, por outro lado, melhora mais com pesos altos.', '', 'Se você treina em casa ou com pouco peso, também evolui.'),
 '2026-12-20': ('Não é preciso chegar à falha', 'Uma meta-análise que comparou treinar até a falha com não chegar à falha não encontrou diferenças significativas no crescimento muscular. Parar a 1 a 3 repetições da falha gera menos fadiga e deixa você se recuperar melhor para a próxima sessão, desde que as séries sejam exigentes.', '', 'Treinar perto da falha basta: menos risco e o mesmo ganho.'),
 '2026-12-21': ('Cardio em jejum: a mesma gordura perdida', 'Um estudo de 4 semanas com mulheres jovens em déficit calórico comparou fazer cardio em jejum com fazê-lo depois de comer. Os dois grupos perderam peso e gordura por igual. O que decide é o balanço do dia, não o horário da sessão.', '', 'Para você treinar no horário que for melhor, não por mitos.'),
 '2026-12-22': (None, 'Netflix', 'Ganhou o Oscar de melhor documentário; sobre doping', 'O que acontece quando se busca render a qualquer preço. No PandarIA, nada de atalhos.'),
 '2026-12-23': ('A fibra que quase ninguém come', 'Uma grande análise encomendada pela OMS descobriu que quem come de 25 a 29 g de fibra por dia tem de 15 a 30 % menos mortalidade e menos doenças do coração, diabetes tipo 2 e câncer colorretal do que quem come pouca.', '', 'Um truque simples para comer melhor e ficar mais saciado.'),
 '2026-12-24': (None, 'YouTube · Spotify · Amazon Music', 'Não está no Apple Podcasts. Em espanhol', 'Reflexões curtas sobre a vida e a constância, para ouvir enquanto caminha.'),
 '2026-12-25': ('Hoje aproveite sem culpa', 'Uma refeição farta não desfaz semanas de trabalho: o que muda seu corpo é o que você repete todo dia, não o que faz num dia. Aproveite a ceia com os seus, beba água e, se quiser, saia para caminhar 10 minutos depois de comer: ajuda a baixar o pico de açúcar no sangue.', '', 'Aproveitar também faz parte de uma vida saudável. Feliz Natal!'),
 '2026-12-26': ('Comer demais não dá mais músculo', 'Atletas de elite que seguiram um plano com superávit calórico ganharam mais peso do que quem comeu livremente, mas grande parte desse peso extra foi gordura. Um superávit moderado é suficiente para ganhar músculo.', '', 'Para ganhar músculo sem ganhar gordura demais.'),
 '2026-12-27': ('Como se hidratar ao treinar', 'O consenso internacional de 2015 sobre hiponatremia associada ao exercício recomenda beber quando sentir sede, não além disso: forçar-se a beber demais dilui o sódio no sangue e já causou mortes em atletas. Em sessões longas ou com calor, pese-se antes e depois: cada quilo perdido é aproximadamente um litro de suor, e para repor recomenda-se beber de 1,25 a 1,5 litro por quilo, de preferência com um pouco de sal ou comida.', '', 'Diz quanto beber antes, durante e depois de treinar.'),
 '2026-12-28': ('O Homem que Confundiu sua Mulher com um Chapéu – Oliver Sacks (1985)', 'Livrarias · eBook', 'Casos neurológicos reais contados por um neurologista', 'Como o cérebro constrói quem você é. A primeira força vem daí.'),
 '2026-12-29': ('Alongar muito antes de levantar tira força', 'Uma grande revisão descobriu que manter um alongamento estático por mais de 60 segundos por músculo logo antes de treinar reduz um pouco a força e a potência imediatas, enquanto os alongamentos curtos quase não afetam. Para aquecer, melhor movimento e séries leves do próprio exercício.', '', 'Para aquecer bem sem perder força antes de levantar.'),
 '2026-12-30': ('Fallout (temporadas 1 e 2)', 'Prime Video', 'Série para adultos', 'Recuperar também é treinar: uma série para seu dia de folga.', ('Cobra Kai', 'Netflix', 'Para maiores de 14', 'Constância, disciplina e segundas chances, num tatame.')),
 '2026-12-31': ('O 16:8 não tem mágica', 'Dois ensaios clínicos importantes compararam comer numa janela de horário com uma dieta normal das mesmas calorias: um de 12 semanas com 116 adultos e outro de um ano com 139 pessoas com obesidade. Em nenhum o horário restrito levou a mais perda de peso. Sua vantagem é que facilita comer menos para algumas pessoas.', '', 'O melhor jejum é o que você consegue manter.'),
 '2027-01-01': ('Metas que duram: comece pequeno', 'Um estudo acompanhou 96 pessoas enquanto criavam um hábito novo: levaram em média 66 dias para torná-lo automático, com muita variação entre pessoas, e falhar um dia não arruinou o processo. Comece com algo pequeno que possa repetir, escolha quando e onde fará, e deixe o PandarIA contar.', '', 'Sua sequência e seus 66 dias começam com um passo pequeno. Feliz Ano Novo!'),
 '2027-01-02': ('Musculação aos 90 anos', 'Pessoas de 90 anos que fizeram 8 semanas de treino de força intenso aumentaram a força em 174 % em média e ganharam massa muscular nas coxas. Nunca é tarde para começar.', '', 'Nunca é tarde para começar a ganhar força.'),
 '2027-01-03': ('I Had Some Help – Post Malone e Morgan Wallen', 'YouTube · Spotify · Apple Music', '', 'Para treinar acompanhado: pedir ajuda também é avançar.'),
 '2027-01-04': ('O metabolismo se adapta', 'Seis anos depois de um concurso de perda de peso na TV, os participantes gastavam em repouso cerca de 500 kcal por dia a menos do que o esperado para o seu tamanho. O corpo se defende quando você perde muito peso, e por isso mantê-lo exige constância.', '', 'Para não desanimar quando o peso empaca.'),
 '2027-01-05': ('Creatina: o suplemento mais estudado', 'A Sociedade Internacional de Nutrição Esportiva considera a creatina o suplemento mais eficaz para aumentar a capacidade de treino de alta intensidade e a massa magra, e segura em pessoas saudáveis nas doses recomendadas (3 a 5 g por dia). Se você tem alguma doença renal, consulte antes.', '', 'Se pensa em tomar algo, comece pelo que tem mais ciência por trás.'),
 '2027-01-06': ('Descansar 3 minutos dá mais músculo', 'Num estudo de 8 semanas com homens treinados, quem descansava 3 minutos entre as séries ganhou mais espessura muscular nas coxas e mais força do que quem descansava 1 minuto. Descansar o suficiente permite levantar mais nas séries seguintes.', '', 'Descansar entre as séries não é perder tempo.'),
 '2027-01-07': ('Contos de H. P. Lovecraft', 'Grátis e legal no Wikisource (domínio público) · Livrarias', 'As traduções das editoras têm direitos próprios', 'Contos curtos para ler antes de dormir em vez de olhar o celular: seu sono agradece.'),
 '2027-01-08': ('Render no Ramadã', 'Uma revisão sobre atletas que jejuam do amanhecer ao pôr do sol durante o Ramadã concluiu que o desempenho pode se manter se cuidarem do horário do treino, do sono, da hidratação e do que comem nas horas permitidas.', '', 'Se você jejua por fé, também pode treinar com inteligência.'),
 '2027-01-09': ('Ultraprocessados: 500 kcal a mais por dia', '20 adultos viveram um mês num centro de pesquisa: duas semanas com comida ultraprocessada e duas com comida pouco processada, comendo o quanto quisessem. Com ultraprocessados comeram cerca de 500 kcal a mais por dia e ganharam quase um quilo em duas semanas.', '', 'Comer menos processados ajuda sem contar cada caloria.'),
 '2027-01-10': ('Água antes de comer', 'Num ensaio de 12 semanas com adultos de 55 a 75 anos em dieta, quem bebia 500 ml de água 30 minutos antes de cada refeição perdeu cerca de 2 kg a mais do que quem só fazia a dieta. Atenção: com a idade a sede diminui, então os mais velhos devem beber mesmo sem muita sede.', '', 'Um hábito simples que pode ajudar você a comer menos.'),
 '2027-01-11': ('Abdominais não queimam a barriga', 'Num estudo, 6 semanas de exercícios abdominais não reduziram a gordura da barriga nem a circunferência da cintura mais do que no grupo que não os fez. A gordura se perde do corpo todo, não da região que você treina.', '', 'Para você não perder tempo com o que não funciona.'),
 '2027-01-12': ('Quanta proteína para ganhar músculo', 'Uma meta-análise de 49 estudos com mais de 1.800 pessoas descobriu que o benefício da proteína para ganhar músculo se estabiliza em 1,6 g por quilo de peso por dia, embora algumas pessoas possam aproveitar até cerca de 2,2 g.', '', 'Para saber quanta proteína é a certa para você.'),
 '2027-01-13': (None, 'PC · PS4 · PS5 · Xbox One · Xbox Series X|S', 'PEGI 18', 'Planejar, se adaptar e ter paciência, como um bom programa de treino. Para seu dia de folga.', ('Ring Fit Adventure (2019)', 'Nintendo Switch', '', 'Um videogame que faz você se mexer de verdade.')),
 '2027-01-14': (None, 'YouTube · Spotify · Apple Music', '', 'Recomeçar com vontade, como seu treino depois das festas.'),
 '2027-01-15': ('O músculo cresce até 48 horas depois', 'O treino é só o sinal. Medindo a síntese de proteína muscular, viu-se que após uma sessão de musculação ela se mantém elevada por até 48 horas em pessoas não treinadas. O músculo é construído enquanto você descansa e come, não enquanto levanta.', '', 'Por isso seu plano deixa dias entre treinos do mesmo músculo.'),
 '2027-01-16': ('Jantar cedo também conta', 'Num ensaio com homens com pré-diabetes, comer tudo dentro de 6 horas e terminar antes das 15h melhorou a sensibilidade à insulina e a pressão arterial em 5 semanas, sem perda de peso. É um estudo pequeno, mas sugere que o horário também importa.', '', 'Não precisa de um jejum longo: jantar mais cedo também ajuda.'),
 '2027-01-17': ('Quanto açúcar a OMS recomenda', 'A OMS recomenda que o açúcar adicionado seja menos de 10 % das calorias diárias, e idealmente menos de 5 %: cerca de 25 gramas numa dieta de 2.000 kcal. Uma única lata de refrigerante pode passar disso.', '', 'Para reduzir o açúcar sem se proibir nada.'),
 '2027-01-18': ('Perder devagar protege o músculo', 'Atletas de elite que perderam 0,7 % do peso por semana ganharam massa magra e força, enquanto quem perdeu 1,4 % por semana não ganhou massa magra. Perder um pouco mais devagar conserva melhor o músculo.', '', 'Perder devagar é o jeito de conservar o que custou tanto ganhar.'),
 '2027-01-19': (None, 'Livrarias · eBook', 'O romance do Grande Irmão', 'Um clássico que convida você a pensar por si mesmo, também diante das modas do fitness.'),
 '2027-01-20': ('A memória muscular existe', 'Em camundongos, os núcleos que as fibras musculares ganham ao crescer se mantêm por meses mesmo que o músculo atrofie. Isso ajudaria a explicar por que você recupera o músculo muito mais rápido depois de uma pausa.', '', 'Se você parar um tempo, vai recuperar antes do que imagina.'),
 '2027-01-21': ('Eu Sou Rocky (I Play Rocky, 2026)', 'Ainda nos cinemas', '', 'Como nasceu Rocky: constância quando ninguém aposta em você.'),
 '2027-01-22': ('Quantos passos por dia importam', 'Uma meta-análise de 15 estudos com quase 50.000 pessoas descobriu que o risco de morte cai à medida que os passos diários aumentam, até se estabilizar em cerca de 6.000 a 8.000 passos em maiores de 60 anos e de 8.000 a 10.000 em menores de 60.', '', 'Cada passo soma, e não é preciso chegar a 10.000 para notar.'),
 '2027-01-23': ('O peso que vai rápido é água', 'Em dietas de pouquíssimas calorias ou jejuns de vários dias, grande parte do peso perdido no começo é glicogênio e a água que vai com ele. Ao voltar a comer, esse peso volta. A gordura se perde mais devagar do que a balança mostra nesses primeiros dias.', '', 'Para a balança da primeira semana não assustar nem iludir você.'),
 '2027-01-24': (None, 'YouTube · Spotify · Apple Music', 'Letra explícita', 'Energia pura para a última série pesada do dia.', ('Eye of the Tiger – Survivor', 'YouTube · Spotify · Apple Music', '', 'O clássico para a última série pesada do dia.')),
 '2027-01-25': ('A pimenta ajuda pouco', 'Uma meta-análise descobriu que a capsaicina da pimenta aumenta um pouco o gasto de energia e reduz um pouco o apetite, mas o efeito é pequeno, de algumas dezenas de calorias. Dá sabor sem calorias, mas não substitui o déficit.', '', 'Para não esperar milagres de nenhum alimento.'),
 '2027-01-26': (None, 'YouTube · Spotify · Apple Music', 'Letra explícita', 'Um ritmo que muda de repente, como um HIIT.', ("Don't Stop Me Now – Queen", 'YouTube · Spotify · Apple Music', '', 'Energia para não parar no seu HIIT.')),
 '2027-01-27': ('As pulseiras inflam as calorias', 'Stanford testou 7 pulseiras e relógios: a maioria mediu bem o pulso, mas nenhum calculou bem as calorias gastas. O mais preciso errou em média 27 % e o pior, 93 %.', '', 'Para não confiar cegamente nas calorias do relógio.'),
 '2027-01-28': ('Treinar o músculo alongado', 'Num estudo, fazer extensões de tríceps com o braço acima da cabeça, onde o músculo trabalha mais alongado, fez o tríceps crescer mais do que fazê-las com o braço junto ao corpo. Trabalhar a amplitude completa, sobretudo a parte alongada, está associado a mais músculo. É uma evidência recente e ainda em estudo.', '', 'Uma forma nova de treinar com evidência recente.'),
 '2027-01-29': ('Dormir pouco faz perder músculo', 'Pessoas em dieta dormiram 8,5 ou 5,5 horas durante duas semanas. Perderam peso parecido, mas dormindo pouco perderam 55 % menos gordura e 60 % mais massa magra, e sentiram mais fome.', '', 'Dormir faz parte do seu plano, não é um extra.'),
 '2027-01-30': ('As amêndoas têm menos calorias', 'Medido em pessoas, um punhado de 28 g de amêndoas fornece cerca de 129 kcal, não as 170 do rótulo. Parte da gordura fica presa nas paredes das células e não é absorvida.', '', 'Um exemplo de que nem todas as calorias do rótulo contam igual.'),
 '2027-01-31': ('O que fazem as pessoas que mantêm o peso', 'O Registro Nacional de Controle de Peso dos Estados Unidos acompanha milhares de pessoas que perderam muito peso e o mantêm. A maioria faz cerca de uma hora de atividade por dia, toma café da manhã, se pesa com frequência e come de forma parecida todos os dias.', '', 'Os costumes de quem conseguiu, para você adotar os que servirem.'),
}
